mapper.select:
SELECT id, project_code, chapter_number, profile, generation_id, memory_mode, canonical_requested, canonical_hit, legacy_fallback_requested, legacy_fallback_hit, candidate_count, filtered_count, selected_count, trimmed_count, retrieval_latency_ms, estimated_tokens, not_found_count, retrieval_miss_count, intentional_trim_count, budget_trim_count, context_items_json, created_at FROM memory_retrieval_metrics WHERE project_code = #{projectCode}
AND chapter_number = #{chapterNumber}
AND profile = #{profile}
AND generation_id = #{generationId}
ORDER BY created_at ASC, id ASC
